g = 2
k = 3

def hasher(data):
    return int(hashlib.sha256(str(data).encode()).hexdigest(), 16)

def try_decrypt(key_str):
    try:
        key = hashlib.sha256(str(key_str).encode()).digest()
        with open('encrypted.txt', 'r') as f:
            data = f.read().strip()
        parts = data.split(':')
        if len(parts) != 3:
            return None
        iv = bytes.fromhex(parts[1])
        ct = bytes.fromhex(parts[2])
        cipher = AES.new(key, AES.MODE_CBC, iv)
        pt = unpad(cipher.decrypt(ct), 16)
        return pt.decode() if b'flag{' in pt else None
    except Exception:
        return None

def get_user_data(username):
    url = 'http://crypto.chal.csaw.io:5000/'
    headers = {
        'Content-Type': 'application/x-www-form-urlencoded'
    }
    data = {
        'username': username,
        'token1': str(g)
    }

    for _ in range(3):
        try:
            response = requests.post(url, data=data, headers=headers)
            if response.status_code == 200:
                try:
                    resp_data = response.json()
                    return {
                        'salt': int(resp_data['nacl']),
                        'B': int(resp_data['token2'])
                    }
                except json.JSONDecodeError:
                    # Try to extract values using regex if JSON parse fails
                    nacl_match = re.search(r'"nacl":\s*"?(\d+)"?', response.text)
                    token2_match = re.search(r'"token2":\s*"?(\d+)"?', response.text)
                    if nacl_match and token2_match:
                        return {
                            'salt': int(nacl_match.group(1)),
                            'B': int(token2_match.group(1))
                        }
            time.sleep(1)
        except Exception as e:
            print(f"Error: {e}")
            time.sleep(1)
    return None

def is_perfect_square(n):
    root = isqrt(n)
    return root * root == n

def find_possible_bases(B, v=None):
    candidates = set()

    # Try small factors that could be squared
    for i in range(2, 100):
        if B % i == 0:
            sq = i * i
            if B % sq == 0:
                candidates.add(i)

    # Try perfect squares
    for i in range(2, 1000):
        sq = i * i
        if sq > B:
            break
        if B % sq == 0:
            candidates.add(i)

    return candidates

def verify_password_pattern(salt, B, pwd):
    xH = hasher(str(salt) + str(pwd))
    v = pow(g, xH, N)
    test_B = (k * v + pow(g, 123456789, N)) % N

    # Compare most significant digits
    return str(test_B)[:6] == str(B)[:6]

