#!/usr/bin/env python3
from pwn import *
import json
import time

context.log_level = 'debug'

def test_auth(username, A_value):
    for _ in range(3):  # Try up to 3 times
        try:
            conn = remote("crypto.chal.csaw.io", 5000)
            conn.recvuntil(b"Enter username:")
            conn.sendline(username.encode())
            conn.recvuntil(b"Enter A:")
            conn.sendline(str(A_value).encode())

            response = conn.recvline().decode().strip()
            print(f"Raw response: {response}")

            if response and "Invalid" not in response:
                try:
                    response_data = json.loads(response)
                    return True, response_data.get("nacl"), int(response_data.get("token2"))
                except json.JSONDecodeError:
                    print("Failed to parse JSON response")
            return False, None, None

        except Exception as e:
            print(f"Connection error: {e}")
            time.sleep(2)
        finally:
            try:
                conn.close()
            except:
                pass
    return False, None, None

def main():
    username = "Lakisha"
    A_values = [2, 3, 5, 7]

    print(f"Testing authentication for user: {username}")
    for A in A_values:
        print(f"\nTesting with A = {A}")
        success, salt, B = test_auth(username, A)

        if success:
            print(f"Success!")
            print(f"Salt: {salt}")
            print(f"B: {B}")
        else:
            print(f"Authentication failed for A = {A}")

        time.sleep(2)  # Rate limiting prevention

if __name__ == "__main__":
    main()

